add_products:
mutation {
  addProductsToCart(cartId: "%CART_ID%", cartItems: [{ quantity: %QTY%, sku: "%SKU%" }]) {
    cart { id items { id quantity } total_quantity prices { grand_total { value currency } } }
    user_errors { code message }
  }
}

add_billing_address:
mutation addBillingAddressToCart($cartId: String!, $version: Long!, $address: AddressInput!, $emailAddress: String) {
  updateMyCart(
    actions: [{setBillingAddress: {address: $address}}, {setCustomerEmail: {email: $emailAddress}}]
    version: $version
    id: $cartId
  ) {
    id
    version
    isAbleToCheckout
  }
}

approve_member_payment:
mutation approveMemberPayment($token: String!, $selectedAddressId: String, $preferredShippingAddressId: String, $selectedFundingOptionId: String!, $preferredFundingOptionId: String, $secondaryFundingOptionIds: [String!], $selectedInstallmentOption: InstallmentsInput, $rewards: RewardsInput, $preAuthorizationRequired: Boolean, $fundingMethodType: FundingInstrumentMethodType, $shareAddressWithDonatee: Boolean, $setStickyFiRequired: Boolean, $scaCompleted: Boolean!, $experiences: [ThreeDSPaymentExperience], $cryptocurrencyQuoteId: String) {
  approveMemberPayment(token: $token, selectedAddressId: $selectedAddressId, preferredShippingAddressId: $preferredShippingAddressId, primaryFundingOptionId: $selectedFundingOptionId, preferredFundingOptionId: $preferredFundingOptionId, secondaryFundingOptionIds: $secondaryFundingOptionIds, selectedInstallmentOption: $selectedInstallmentOption, rewards: $rewards, preAuthorizationRequired: $preAuthorizationRequired, fundingMethodType: $fundingMethodType, shareAddressWithDonatee: $shareAddressWithDonatee, setStickyFiRequired: $setStickyFiRequired, strongCustomerAuthenticationCompleted: $scaCompleted, cryptocurrencyQuoteId: $cryptocurrencyQuoteId) {
    state
    buyer {
      userId
      email {
        stringValue
        __typename
      }
      name {
        fullName
        __typename
      }
      __typename
    }
    cart {
      intent
      paymentId
      billingToken
      returnUrl {
        href
        pathname
        __typename
      }
      cancelUrl {
        href
        pathname
        __typename
      }
      intent
      items {
        quantity
        name
        sku
        unitPrice {
          currencyValue
          __typename
        }
        itemOptionSelections {
          name
          description
          __typename
        }
        __typename
      }
      amounts {
        subtotal {
          currencyCode
          currencyFormat
          __typename
        }
        tax {
          currencyCode
          currencyFormat
          __typename
        }
        shipping {
          currencyCode
          currencyFormat
          __typename
        }
        insurance {
          currencyCode
          currencyFormat
          __typename
        }
        handlingFee {
          currencyCode
          currencyFormat
          __typename
        }
        total {
          currencyCode
          currencyFormat
          __typename
        }
        discount {
          currencyCode
          currencyFormat
          __typename
        }
        __typename
      }
      __typename
    }
    paymentContingencies {
      ...PaymentContingenciesFragment
      threeDomainSecure(experiences: $experiences) {
        ...ThreeDomainSecureFields
        __typename
      }
      __typename
    }
    completedPaymentInfo {
      transactionId
      transactionState
      softDescriptor
      postbackData
      __typename
    }
    merchant {
      preferences {
        autoReturnToMerchant
        enablePaymentDataTransfer
        returnUrl
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment PaymentContingenciesFragment on PaymentContingencies {
  confirmCreditCardCvvData {
    ...ConfirmCreditCardCvvFields
    __typename
  }
  sepaMandateAcceptanceNeeded {
    ...SepaMandateAcceptanceNeededFragment
    __typename
  }
  threeDomainSecure(experiences: $experiences) {
    ...ThreeDomainSecureFields
    __typename
  }
  threeDSContingencyData {
    ...ThreeDomainSecureContingencyFragment
    __typename
  }
  needConsentForBankAccountInfoRetrieval {
    encryptedId
    __typename
  }
  needRealTimeBalanceForBankAccount {
    encryptedId
    __typename
  }
  strongCustomerAuthenticationRequired {
    contextId
    __typename
  }
  __typename
}

fragment ConfirmCreditCardCvvFields on ConfirmCreditCardCvvContingency {
  encryptedId
  lastFourDigits
  type
  __typename
}

fragment SepaMandateAcceptanceNeededFragment on BankAccount {
  id
  type
  accountNumber
  accountNumberShort
  bankIdentifierCode
  currencyCode
  beneficiaries {
    fullName
    __typename
  }
  billingAddress {
    city
    country
    state
    fullAddress
    __typename
  }
  issuer {
    name
    __typename
  }
  creditor {
    id
    name
    address {
      fullAddress
      __typename
    }
    __typename
  }
  __typename
}

fragment ThreeDomainSecureFields on ThreeDomainSecureContingency {
  redirectUrl {
    href
    __typename
  }
  status
  method
  parameter
  encryptedId
  experience
  requestParams {
    key
    value
    __typename
  }
  __typename
}

fragment ThreeDomainSecureContingencyFragment on ThreeDomainSecureResolutionContingency {
  name
  causeName
  resolution {
    type
    resolutionName
    paymentCard {
      id
      type
      number
      encryptedNumber
      bankIdentificationNumber
      billingAddress {
        line1
        line2
        state
        city
        postalCode
        country
        __typename
      }
      expireYear
      expireMonth
      currencyCode
      cardProductClass
      __typename
    }
    contingencyContext {
      source
      reason
      referenceId
      deviceDataCollectionUrl {
        href
        __typename
      }
      jwtSpecification {
        jwtIssuer
        jwtOrgUnitId
        jwtDuration
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

add_to_cart_query:
query addToCart($sku: String!, $qty: Int!, $type: String, $info: String) {
  addToCart(item: {sku: $sku, qty: $qty, quote_id: "1", type: $type, info: $info}) {
    sku
    message
    status
    cart_id
    qty
    __typename
  }
}

buynow:
query buynow {
  buynow(
    item: {sku: "", qty: 1, quote_id: "1", type: "Simple", bundleOptions: null}
    isNormalBuyFlow: true
  ) {
    status
    cart_id
    session_id
    qty
    message
    __typename
  }
}
